mapper.select:
SELECT c.id, c.content, c.embedding, c.metadata::text AS metadata, c.user_id, c.document_id, c.version, c.parent_id, c.chunk_type, c.title, c.created_at FROM ai_knowledge_chunk c
LEFT JOIN ai_document d ON d.document_id = c.document_id AND d.user_id = c.user_id WHERE c.embedding IS NOT NULL AND c.chunk_type = 'CHILD' AND (1 - (c.embedding <=> #{queryVector, typeHandler=com.example.langchain4j.repository.typehandler.VectorTypeHandler})) >= #{minScore} AND (c.user_id = #{userId} OR (NOT #{privateOnly} AND c.user_id IS NULL))
AND (c.document_id IS NULL OR d.id IS NULL OR c.version = d.active_version) ORDER BY c.embedding <=> #{queryVector, typeHandler=com.example.langchain4j.repository.typehandler.VectorTypeHandler} LIMIT #{topK}

SELECT id, content, embedding, metadata::text AS metadata, user_id,
       document_id, version, parent_id, chunk_type, title, created_at, updated_at
FROM ai_knowledge_chunk
WHERE title = #{title}
  AND chunk_type = 'PARENT'
  AND (user_id IS NULL OR user_id = #{userId})

  AND document_id = #{documentId}


  AND version = #{version}

ORDER BY id

SELECT MAX(version)
FROM ai_knowledge_chunk
WHERE document_id = #{documentId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM ai_knowledge_chunk
WHERE id IN (
    SELECT id
    FROM ai_knowledge_chunk
    WHERE document_id = #{documentId}
      AND user_id = #{userId}
      AND (
          version < #{activeVersion}
          OR (version > #{activeVersion}
              AND created_at < now() - make_interval(hours => #{retentionHours}))
      )
    LIMIT #{batchSize}
)

DELETE FROM ai_knowledge_chunk
WHERE document_id = #{documentId}
  AND version = #{version}
  AND user_id = #{userId}

DELETE FROM ai_knowledge_chunk
WHERE parent_id = #{parentId}
  AND chunk_type = 'CHILD'
  AND user_id = #{userId}

DELETE FROM ai_knowledge_chunk
WHERE id = #{id}
  AND user_id = #{userId}
